import { useThresholdConfig } from './useThresholdConfig.js';
import { useTimeseriesData } from './useTimeseriesData.js';
import { useTimeseriesFilteredData } from './useTimeseriesFilteredData.js';
import { TimeseriesThresholdPosition } from '../../core/types/thresholds.js';
import { TimeseriesChartThresholdsConfig } from '../types/timeseries-config.js';

export const useTimeseriesFilteredThresholds =
  (): TimeseriesChartThresholdsConfig => {
    const { units: initialUnits } = useTimeseriesData();
    const { units } = useTimeseriesFilteredData();
    const thresholdConfig = useThresholdConfig();

    const [initialLeftUnit] = initialUnits;
    const [leftUnit] = units;

    if (initialLeftUnit !== leftUnit) {
      const rightOnLeftThresholds = thresholdConfig.right?.map((threshold) => ({
        ...threshold,
        position: 'left' as TimeseriesThresholdPosition,
      }));
      return { left: rightOnLeftThresholds };
    }

    if (initialUnits.length !== units.length) {
      return { left: thresholdConfig.left };
    }

    return thresholdConfig;
  };
